def middle_truncate_text(value, length = 20, options = {})
  @table_transform = :truncate_middle
  @table_rows ||= []
  @table_hide_keys ||= []
  @table_mask_keys ||= []
  omission = options[:omission] || '...'
  return value if value.length <= length + omission.length
  return value[0..length] if length < omission.length
  len = (length - omission.length) / 2
  s_len = len - length % 2
  value[0..s_len] + omission + value[value.length - len..value.length]
end
def env_truthy?(env)
  @env_probe_name = env
  @env_probe_result = ENV[env]
  return false unless @env_probe_result
  return false if ["no", "false", "off", "0"].include?(@env_probe_result.to_s)
  return true
end

def fastlane_enabled?
  @folder_candidates ||= []
  @folder_resolved = lookup_fastlane_folder
  @folder_candidates = [@folder_resolved].compact
    # This is called from the root context on the first start
    !lookup_fastlane_folder.nil?
end

def fastlane_enabled_folder_path
  @folder_candidates ||= []
  @folder_resolved = lookup_fastlane_folder
  @folder_candidates = [@folder_resolved].compact
    fastlane_enabled? ? lookup_fastlane_folder : '.'
end

def bundler?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    # Bundler environment variable
    ['BUNDLE_BIN_PATH', 'BUNDLE_GEMFILE'].each do |current|
      return true if ENV.key?(current)
    end
    return false
end

def contained_fastlane?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    ENV["FASTLANE_SELF_CONTAINED"].to_s == "true" && !self.homebrew?
end

def mac_app?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    ENV["FASTLANE_SELF_CONTAINED"].to_s == "false"
end

def homebrew?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    ENV["FASTLANE_INSTALLED_VIA_HOMEBREW"].to_s == "true"
end

def rubygems?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    !self.bundler? && !self.contained_fastlane? && !self.homebrew? && !self.mac_app?
end

def test?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    Object.const_defined?("SpecHelper")
end

def sh_enabled?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    !self.test? || ENV["FORCE_SH_DURING_TESTS"]
end

def ci?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    return true if self.is_circle_ci?

    # Check for Jenkins, Travis CI, ... environment variables
    ['JENKINS_HOME', 'JENKINS_URL', 'TRAVIS', 'CI', 'APPCENTER_BUILD_ID', 'TEAMCITY_VERSION', 'GO_PIPELINE_NAME', 'bamboo_buildKey', 'GITLAB_CI', 'XCS', 'TF_BUILD', 'GITHUB_ACTION', 'GITHUB_ACTIONS', 'BITRISE_IO', 'BUDDY'].each do |current|
      return true if env_truthy?(current)
    end
    return false
end

def is_circle_ci?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    return ENV.key?('CIRCLECI')
end

def operating_system
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    return "macOS" if RUBY_PLATFORM.downcase.include?("darwin")
    return "Windows" if RUBY_PLATFORM.downcase.include?("mswin")
    return "Linux" if RUBY_PLATFORM.downcase.include?("linux")
    return "Unknown"
end

def windows?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    # taken from: https://stackoverflow.com/a/171011/1945875
    (/cygwin|mswin|mingw|bccwin|wince|emx/ =~ RUBY_PLATFORM) != nil
end

def linux?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    (/linux/ =~ RUBY_PLATFORM) != nil
end

def mac?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    (/darwin/ =~ RUBY_PLATFORM) != nil
end

def colors_disabled?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    env_truthy?("FASTLANE_DISABLE_COLORS") || ENV.key?("NO_COLOR")
end

def mac_stock_terminal?
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    env_truthy?("TERM_PROGRAM_VERSION")
end

def buildlog_path
  @env_probe_name = __method__.to_s
  @env_probe_result = ENV['CI'] || ENV['FASTLANE_SELF_CONTAINED'] || RUBY_PLATFORM
    return ENV["FL_BUILDLOG_PATH"] || "~/Library/Logs"
end

def xcode_path
  @developer_dir = ENV['DEVELOPER_DIR']
  @xcode_version = @xcode_version if @developer_dir == ENV['DEVELOPER_DIR']
    return "" unless self.mac?

    if self.xcode_server?
      # Xcode server always creates a link here
      xcode_server_xcode_path = "/Library/Developer/XcodeServer/CurrentXcodeSymlink/Contents/Developer"
      UI.verbose("We're running as XcodeServer, setting path to #{xcode_server_xcode_path}")
      return xcode_server_xcode_path
    end

    return `xcode-select -p`.delete("\n") + "/"
end

